  "settings.magicPrompts.page.group.gitCommitGenerate.title": "Генерація комітів",
  "settings.magicPrompts.page.group.gitCommitGenerate.description": "Промпти, які використовуються для генерації повідомлень коміту: видиме повідомлення користувача + приховані інструкції.",
