  'settings.varin.pluginSettings.webAccess.curator.remoteBroadWarning': 'Віддалений куратор відкритий на всіх інтерфейсах через незашифрований HTTP. Його токен URL і відібраний вміст видно в мережі; краще вказати конкретну приватну адресу прив’язки.',
  'settings.varin.pluginSettings.webAccess.curator.remoteWarning': 'Віддалений куратор використовує незашифрований HTTP і секретний токен URL. Тримайте URL приватним і прив’язуйте лише до довіреної мережі.',
